diff --git a/js/checkoutBranch.js b/js/checkoutBranch.js
index 12f2c8202..0e32d1000 100644
--- a/js/checkoutBranch.js
+++ b/js/checkoutBranch.js
@@ -93,11 +93,45 @@ function establishFeatureBranch(config, customParams, ticket) {
     });
 }

+/**
+ * gh-1301 resume-leg alignment: drop untracked input/ per-run artifacts
+ * before the dev-branch checkout. A leg that ended in ask-mode pushes
+ * ai/<ticket> with the session timer's auto-committed input/<ticket>/ copies;
+ * a leg re-running the same ticket (comment-resume, retry) regenerates those
+ * files and git refuses the checkout ("would be overwritten by checkout").
+ * input/ is a per-run artifact drop — remove untracked collisions (tracked
+ * files are untouched) so the re-run aligns with the existing branch,
+ * mirroring the .codegraph guard pattern. Best-effort: probe/removal failures
+ * warn and never block the checkout.
+ */
+function dropUntrackedInputArtifacts() {
+    try {
+        var statusOut = prHelper.cleanCommandOutput(
+            runCommandForProbes('git status --porcelain -- input/') || '');
+        var statusLines = statusOut.split('\n');
+        for (var si = 0; si < statusLines.length; si++) {
+            var statusLine = statusLines[si];
+            if (statusLine.substring(0, 2) === '??') {
+                var stalePath = statusLine.substring(3).trim();
+                if (!stalePath) continue;
+                console.log('Removing untracked per-run artifact before checkout:', stalePath);
+                try { cli_execute_command({ command: 'bash -c "rm -rf ' + stalePath + '"' }); } catch (e) {
+                    console.warn('Could not remove stale artifact ' + stalePath + ':', e);
+                }
+            }
+        }
+    } catch (e) {
+        console.warn('Input-artifact cleanup before checkout failed:', e);
+    }
+}
+
 /**
  * Dev-branch checkout decision tree: exists locally → plain checkout;
  * exists on remote → tracking checkout; absent → create from branchBase.
  */
 function checkoutDevBranch(branchName, branchBase) {
+    dropUntrackedInputArtifacts();
+
     var localBranches = readLocalBranchList(branchName, 'Error checking local branches:');
     if (localBranches.trim()) {
         // Branch exists locally — check it out
@@ -163,6 +197,7 @@ if (typeof module !== 'undefined' && module.exports) {
         probeRemoteBranch: probeRemoteBranch,
         createFeatureBranch: createFeatureBranch,
         establishFeatureBranch: establishFeatureBranch,
-        checkoutDevBranch: checkoutDevBranch
+        checkoutDevBranch: checkoutDevBranch,
+        dropUntrackedInputArtifacts: dropUntrackedInputArtifacts
     };
 }

+
     var localBranches = readLocalBranchList(branchName, 'Error checking local branches:');
     if (localBranches.trim()) {
         // Branch exists locally — check it out
@@ -163,6 +197,7 @@ if (typeof module !== 'undefined' && module.exports) {
         probeRemoteBranch: probeRemoteBranch,
         createFeatureBranch: createFeatureBranch,
         establishFeatureBranch: establishFeatureBranch,
-        checkoutDevBranch: checkoutDevBranch
+        checkoutDevBranch: checkoutDevBranch,
+        dropUntrackedInputArtifacts: dropUntrackedInputArtifacts
     };
 }
diff --git a/js/developTicketAndCreatePR.js b/js/developTicketAndCreatePR.js
index e90b928a2..40fe9b039 100644
--- a/js/developTicketAndCreatePR.js
+++ b/js/developTicketAndCreatePR.js
@@ -1417,7 +1417,62 @@ function resetInterruptedDevelopment(ctx, commentBody) {
     throwInterruptedReset(ctx.ticketKey);
 }

+// ── inputs pre-flight (ask-mode) seam ───────────────────────────────────────
+// Both ask-mode exits share the same bookkeeping: label the ticket as waiting
+// on the reporter (best-effort) and end the leg GREEN with a needsInput
+// outcome — no PR, no interrupted reset.
+
+/** Best-effort ai_questions_asked label — the reviewer hand-off reads it. */
+function markNeedsInputTicket(ctx) {
+    try {
+        getTracker().addLabel(ctx.ticketKey, LABELS.AI_QUESTIONS_ASKED);
+    } catch (e) {
+        console.warn('Could not add ' + LABELS.AI_QUESTIONS_ASKED + ' label:', e);
+    }
+}
+
+/** The green outcome body shared by both ask-mode exits. */
+function needsInputOutcomeBody(ctx) {
+    return {
+        success: true,
+        message: 'Ticket ' + ctx.ticketKey + ' needs input from the reporter — question posted, no PR created',
+        needsInput: true
+    };
+}
+
+/**
+ * Ask-mode (no-assumptions rule) — the agent flagged missing ticket inputs
+ * and stopped WITHOUT writing response.md (the question comment is already
+ * posted; outputs/needs-input.md marks the leg). This check MUST precede the
+ * interrupted classification in recoverNoChangesOutcome: a response.md-less
+ * ask leg is exactly where the ticket should be — waiting on the reporter —
+ * never an interrupted reset, and the reviewer hand-off skips ask-mode via
+ * the same label. Returns null when the leg is not an ask-mode leg.
+ */
+function askModeOutcome(ctx) {
+    if (!outputFiles.hasOutputFile('needs-input.md')) return null;
+    console.log('outputs/needs-input.md present — ask-mode leg: agent asked for missing inputs. No PR, no reset.');
+    markNeedsInputTicket(ctx);
+    return { result: needsInputOutcomeBody(ctx) };
+}
+
